#include <stdio.h>

/* teste do desafio ficha-numerada — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout
   para o arquivo temporario, o teste chama a funcao do aluno e le de volta.
   A frase e comparada INTEIRA: um %d na ordem errada muda a linha. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void fichaNumerada(void);

SM_TEST(a_frase_com_os_dois_numeros) {
    freopen("sm_saida.tmp", "w", stdout);
    fichaNumerada();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o titulo da ficha", linha, "ficha da turma C1\n",
              "a ficha abre pelo titulo, que ja vinha escrito");
    fgets(linha, 80, f);
    checa_str("a frase com os dois numeros", linha, "3 provas e 12 aulas\n",
              "cada %d consome um valor inteiro, na ordem: primeiro 3, depois 12");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

